import Foundation
import MajordomoCore

enum AppUILanguage: String, CaseIterable {
    case system = "system"
    case english = "en"
    case polish = "pl"
    case german = "de"
    case french = "fr"
    case spanish = "es"
    case italian = "it"
    case portuguese = "pt"

    static let userDefaultsKey = DefaultsKey.appUILanguage

    static var current: AppUILanguage {
        if let override = ProcessInfo.processInfo.environment["MAJORDOMO_UI_LANGUAGE"]?.lowercased(),
           let language = AppUILanguage(rawValue: String(override.prefix(2))) {
            return language
        }

        return selectedPreference.resolvedLanguage
    }

    static var selectedPreference: AppUILanguage {
        guard let rawValue = UserDefaults.standard.string(forKey: userDefaultsKey),
              let language = AppUILanguage(rawValue: rawValue) else {
            return .system
        }
        return language
    }

    static func persistPreference(_ language: AppUILanguage) {
        UserDefaults.standard.set(language.rawValue, forKey: userDefaultsKey)
    }

    static func resolvedSystemLanguage() -> AppUILanguage {
        for preferred in Locale.preferredLanguages {
            let code = String(preferred.lowercased().prefix(2))
            if let language = AppUILanguage(rawValue: code), language != .system {
                return language
            }
        }

        return .english
    }

    var resolvedLanguage: AppUILanguage {
        self == .system ? Self.resolvedSystemLanguage() : self
    }

    var localeIdentifier: String { resolvedLanguage.rawValue }

    var displayName: String {
        switch self {
        case .system:
            return L10n.text("app_language.system")
        case .english:
            return "English"
        case .polish:
            return "Polski"
        case .german:
            return "Deutsch"
        case .french:
            return "Français"
        case .spanish:
            return "Español"
        case .italian:
            return "Italiano"
        case .portuguese:
            return "Português"
        }
    }
}

