        "error.model.missing": [.english: "%@ model is missing at %@. Select %@ again to download it on demand.", .polish: "Model %@ nie istnieje w %@. Wybierz ponownie %@, aby pobrać go na żądanie.", .german: "Das Modell %@ fehlt unter %@. Wählen Sie %@ erneut aus, um es bei Bedarf herunterzuladen.", .french: "Le modèle %@ est absent de %@. Sélectionnez à nouveau %@ pour le télécharger à la demande.", .spanish: "El modelo %@ falta en %@. Seleccione %@ de nuevo para descargarlo bajo demanda.", .italian: "Il modello %@ manca in %@. Seleziona di nuovo %@ per scaricarlo su richiesta.", .portuguese: "O modelo %@ está ausente em %@. Selecione %@ novamente para o transferir a pedido."],
        "error.model.invalid_http": [.english: "Couldn’t download the speech model. Check your internet connection and try again.", .polish: "Nie udało się pobrać modelu mowy. Sprawdź połączenie z internetem i spróbuj ponownie.", .german: "Das Sprachmodell konnte nicht geladen werden. Prüfe deine Internetverbindung und versuche es erneut.", .french: "Impossible de télécharger le modèle vocal. Vérifiez votre connexion internet et réessayez.", .spanish: "No se pudo descargar el modelo de voz. Comprueba tu conexión a internet e inténtalo de nuevo.", .italian: "Impossibile scaricare il modello vocale. Controlla la connessione a internet e riprova.", .portuguese: "Não foi possível transferir o modelo de voz. Verifica a ligação à internet e tenta novamente."],
        "error.model.download_failed": [.english: "Couldn’t download the speech model. Check your internet connection and try again.", .polish: "Nie udało się pobrać modelu mowy. Sprawdź połączenie z internetem i spróbuj ponownie.", .german: "Das Sprachmodell konnte nicht geladen werden. Prüfe deine Internetverbindung und versuche es erneut.", .french: "Impossible de télécharger le modèle vocal. Vérifiez votre connexion internet et réessayez.", .spanish: "No se pudo descargar el modelo de voz. Comprueba tu conexión a internet e inténtalo de nuevo.", .italian: "Impossibile scaricare il modello vocale. Controlla la connessione a internet e riprova.", .portuguese: "Não foi possível transferir o modelo de voz. Verifica a ligação à internet e tenta novamente."],
        "error.model.too_small": [.english: "The model download was incomplete. Select the model again to retry.", .polish: "Pobieranie modelu było niekompletne. Wybierz model ponownie, aby spróbować jeszcze raz.", .german: "Der Modell-Download war unvollständig. Wähle das Modell erneut aus, um es noch einmal zu versuchen.", .french: "Le téléchargement du modèle était incomplet. Sélectionnez à nouveau le modèle pour réessayer.", .spanish: "La descarga del modelo quedó incompleta. Selecciona el modelo de nuevo para reintentar.", .italian: "Il download del modello è incompleto. Seleziona di nuovo il modello per riprovare.", .portuguese: "A transferência do modelo ficou incompleta. Seleciona o modelo novamente para tentar de novo."],
        "error.model.checksum_mismatch": [.english: "The downloaded model looks corrupted. Select the model again to download it fresh.", .polish: "Pobrany model wygląda na uszkodzony. Wybierz model ponownie, aby pobrać go na nowo.", .german: "Das geladene Modell scheint beschädigt. Wähle das Modell erneut aus, um es neu zu laden.", .french: "Le modèle téléchargé semble corrompu. Sélectionnez à nouveau le modèle pour le retélécharger.", .spanish: "El modelo descargado parece dañado. Selecciona el modelo de nuevo para volver a descargarlo.", .italian: "Il modello scaricato sembra danneggiato. Seleziona di nuovo il modello per riscaricarlo.", .portuguese: "O modelo transferido parece corrompido. Seleciona o modelo novamente para o transferir de novo."],
