        "about.window_title": [.english: "About Majordomo", .polish: "O aplikacji Majordomo", .german: "Über Majordomo", .french: "À propos de Majordomo", .spanish: "Acerca de Majordomo", .italian: "Informazioni su Majordomo", .portuguese: "Sobre o Majordomo"],
        "about.subtitle": [.english: "Hands off the keyboard. Voice on the bridge.", .polish: "Ręce z dala od klawiatury. Głos przejmuje ster.", .german: "Hände weg von der Tastatur. Die Stimme übernimmt das Kommando.", .french: "Laissez le clavier. La voix prend le relais.", .spanish: "Deja el teclado. La voz toma el mando.", .italian: "Via le mani dalla tastiera. La voce prende il comando.", .portuguese: "Longe do teclado. A voz assume o comando."],
        "about.text": [.english: "Application\n-----------\nMajordomo\nVersion: %@ (%@)\nPlatform: macOS\n\nMajordomo records microphone audio only for local speech-to-text. Audio and transcripts stay on this Mac. The app has no telemetry and keeps no transcript history.\n\nMajordomo License\n-----------------\nMajordomo is open source under the MIT License.\nYou may use, copy, modify, and distribute it freely.\nThe full license text is in the LICENSE file.\n\n%@", .polish: "Aplikacja\n---------\nMajordomo\nWersja: %@ (%@)\nPlatforma: macOS\n\nMajordomo nagrywa audio z mikrofonu wyłącznie do lokalnej zamiany mowy na tekst. Audio i transkrypcje pozostają na tym Macu. Aplikacja nie ma telemetrii i nie przechowuje historii transkrypcji.\n\nLicencja Majordomo\n------------------\nMajordomo jest oprogramowaniem open source na licencji MIT.\nMożesz go swobodnie używać, kopiować, modyfikować i rozpowszechniać.\nPełny tekst licencji znajduje się w pliku LICENSE.\n\n%@", .german: "Anwendung\n----------\nMajordomo\nVersion: %@ (%@)\nPlattform: macOS\n\nMajordomo zeichnet Mikrofonaudio nur für lokale Spracherkennung auf. Audio und Transkripte bleiben auf diesem Mac. Die App enthält keine Telemetrie und speichert keinen Transkriptverlauf.\n\nMajordomo-Lizenz\n----------------\nMajordomo ist Open-Source-Software unter der MIT-Lizenz.\nDu darfst sie frei verwenden, kopieren, ändern und weitergeben.\nDer vollständige Lizenztext steht in der LICENSE-Datei.\n\n%@", .french: "Application\n-----------\nMajordomo\nVersion : %@ (%@)\nPlateforme : macOS\n\nMajordomo enregistre l’audio du microphone uniquement pour la transcription locale de la parole. L’audio et les transcriptions restent sur ce Mac. L’application n’intègre aucune télémétrie et ne conserve aucun historique des transcriptions.\n\nLicence Majordomo\n-----------------\nMajordomo est un logiciel open source sous licence MIT.\nVous pouvez l’utiliser, le copier, le modifier et le distribuer librement.\nLe texte complet de la licence se trouve dans le fichier LICENSE.\n\n%@", .spanish: "Aplicación\n----------\nMajordomo\nVersión: %@ (%@)\nPlataforma: macOS\n\nMajordomo graba audio del micrófono solo para la transcripción local de voz a texto. El audio y las transcripciones permanecen en este Mac. La aplicación no tiene telemetría ni guarda historial de transcripciones.\n\nLicencia de Majordomo\n---------------------\nMajordomo es software de código abierto bajo la licencia MIT.\nPuedes usarlo, copiarlo, modificarlo y distribuirlo libremente.\nEl texto completo de la licencia está en el archivo LICENSE.\n\n%@", .italian: "Applicazione\n------------\nMajordomo\nVersione: %@ (%@)\nPiattaforma: macOS\n\nMajordomo registra l’audio del microfono solo per la trascrizione vocale locale. Audio e trascrizioni restano su questo Mac. L’app non include telemetria e non conserva una cronologia delle trascrizioni.\n\nLicenza Majordomo\n-----------------\nMajordomo è software open source con licenza MIT.\nPuoi usarlo, copiarlo, modificarlo e distribuirlo liberamente.\nIl testo completo della licenza è nel file LICENSE.\n\n%@", .portuguese: "Aplicação\n----------\nMajordomo\nVersão: %@ (%@)\nPlataforma: macOS\n\nMajordomo grava áudio do microfone apenas para transcrição local de voz para texto. O áudio e as transcrições permanecem neste Mac. A aplicação não tem telemetria nem mantém histórico de transcrições.\n\nLicença do Majordomo\n--------------------\nO Majordomo é software de código aberto sob a licença MIT.\nPodes usá-lo, copiá-lo, modificá-lo e distribuí-lo livremente.\nO texto completo da licença está no ficheiro LICENSE.\n\n%@"],
        "about.notices_unavailable": [.english: "Third-party notices unavailable in this build.", .polish: "Informacje o komponentach zewnętrznych są niedostępne w tej wersji.", .german: "Hinweise zu Drittanbietern sind in dieser Version nicht verfügbar.", .french: "Les mentions des composants tiers ne sont pas disponibles dans cette version.", .spanish: "Los avisos de terceros no están disponibles en esta versión.", .italian: "Le note sui componenti di terze parti non sono disponibili in questa versione.", .portuguese: "Os avisos de terceiros não estão disponíveis nesta versão."]
    ]

    static func text(_ key: String, _ args: CVarArg...) -> String {
        let language = AppUILanguage.current
        let template = table[key]?[language] ?? table[key]?[.english] ?? key
        guard !args.isEmpty else { return template }
        return String(format: template, locale: Locale(identifier: language.localeIdentifier), arguments: args)
    }
}
